styles.content:
/*
 * Ermine UI — design tokens and base styles.
 *
 * Every component reads from the variables below, so this file is the theme.
 * Change a value here and the whole library follows.
 *
 * Dark mode follows the operating system by default. To force a theme, put
 * class="dark" / class="light" (or data-theme="dark" / "light") on <html>,
 * or on any element to theme just that subtree.
 *
 * Layers: component styles live in `@layer components`, so any CSS you write
 * outside a layer wins without needing !important or extra specificity.
 */
@layer base, components;

:root {
  color-scheme: light dark;

  /* Surfaces and text */
  --er-background: light-dark(oklch(1 0 0), oklch(0.145 0 0));
  --er-foreground: light-dark(oklch(0.145 0 0), oklch(0.985 0 0));
  --er-card: light-dark(oklch(1 0 0), oklch(0.205 0 0));
  --er-card-foreground: light-dark(oklch(0.145 0 0), oklch(0.985 0 0));
  --er-popover: light-dark(oklch(1 0 0), oklch(0.225 0 0));
  --er-popover-foreground: light-dark(oklch(0.145 0 0), oklch(0.985 0 0));

  /* Actions */
  --er-primary: light-dark(oklch(0.205 0 0), oklch(0.922 0 0));
  --er-primary-foreground: light-dark(oklch(0.985 0 0), oklch(0.205 0 0));
  --er-secondary: light-dark(oklch(0.965 0 0), oklch(0.269 0 0));
  --er-secondary-foreground: light-dark(oklch(0.205 0 0), oklch(0.985 0 0));
  --er-muted: light-dark(oklch(0.965 0 0), oklch(0.269 0 0));
  --er-muted-foreground: light-dark(oklch(0.5 0 0), oklch(0.708 0 0));
  --er-accent: light-dark(oklch(0.965 0 0), oklch(0.3 0 0));
  --er-accent-foreground: light-dark(oklch(0.205 0 0), oklch(0.985 0 0));
  /* Used both as a fill (buttons, badges) and as text (errors). In the dark theme it is light enough
     to read as text on dark surfaces, so what sits on top of it is dark, as with the primary colour. */
  --er-destructive: light-dark(oklch(0.55 0.22 27), oklch(0.71 0.18 24));
  --er-destructive-foreground: light-dark(oklch(0.985 0 0), oklch(0.16 0.02 25));

  /* Status (toasts, validation) */
  --er-success: light-dark(oklch(0.55 0.15 150), oklch(0.72 0.17 150));
  --er-warning: light-dark(oklch(0.62 0.15 70), oklch(0.8 0.15 80));
  --er-info: light-dark(oklch(0.55 0.16 250), oklch(0.72 0.14 245));

  /* Chart series, in the order they are handed out. The order is what keeps neighbours
     distinguishable for colour-blind readers, so re-check it if you change these. */
  --er-chart-1: light-dark(#2a78d6, #3987e5);
  --er-chart-2: light-dark(#eb6834, #d95926);
  --er-chart-3: light-dark(#1baf7a, #199e70);
  --er-chart-4: light-dark(#eda100, #c98500);
  --er-chart-5: light-dark(#e87ba4, #d55181);
  --er-chart-6: light-dark(#008300, #008300);
  --er-chart-7: light-dark(#4a3aa7, #9085e9);
  --er-chart-8: light-dark(#e34948, #e66767);

  /* Lines and focus */
  --er-border: light-dark(oklch(0.915 0 0), oklch(1 0 0 / 12%));
  --er-input: light-dark(oklch(0.87 0 0), oklch(1 0 0 / 18%));
  --er-input-background: light-dark(transparent, oklch(1 0 0 / 4%));
  --er-ring: light-dark(oklch(0.45 0 0), oklch(0.75 0 0));
  --er-overlay: oklch(0 0 0 / 55%);

  /* Shape */
  --er-radius: 0.625rem;
  --er-radius-sm: calc(var(--er-radius) - 4px);
  --er-radius-md: calc(var(--er-radius) - 2px);
  --er-radius-lg: var(--er-radius);
  --er-radius-xl: calc(var(--er-radius) + 4px);

  /* Type */
  --er-font-sans: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --er-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;

  /* Fluid type (the typography component). Text grows smoothly between a narrow screen and a wide one,
     with no breakpoints. Each size is the body size multiplied by the ratio once per step up the scale.
     Sizes are in rem, so they still follow the reader's own browser text-size setting. */
  --er-type-min: 1; /* body size in rem at the narrow end (1 = 16px by default) */
  --er-type-max: 1.125; /* body size in rem at the wide end */
  --er-type-ratio-min: 1.2; /* how much bigger each step is at the narrow end */
  --er-type-ratio-max: 1.3; /* and at the wide end: headings grow more than body text does */
  --er-type-from: 20rem; /* the width at which text starts growing (320px) */
  --er-type-range: 60; /* how many rem wider than that it stops (60 = stops at 1280px) */

  /* Elevation */
  --er-shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 5%);
  --er-shadow-sm: 0 1px 3px 0 oklch(0 0 0 / 10%), 0 1px 2px -1px oklch(0 0 0 / 10%);
  --er-shadow-md: 0 4px 6px -1px oklch(0 0 0 / 10%), 0 2px 4px -2px oklch(0 0 0 / 10%);
  --er-shadow-lg: 0 10px 15px -3px oklch(0 0 0 / 12%), 0 4px 6px -4px oklch(0 0 0 / 12%);

  /* Motion and stacking */
  --er-duration: 150ms;
  --er-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --er-z-overlay: 50;
  --er-z-toast: 100;
}

.light,
[data-theme='light'] {
  color-scheme: light;
}

.dark,
[data-theme='dark'] {
  color-scheme: dark;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --er-duration: 0ms;
  }
}

@layer base {
  *,
  ::before,
  ::after {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    background: var(--er-background);
    color: var(--er-foreground);
    font-family: var(--er-font-sans);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
  }
}

@layer components {
  /* Shared by everything that floats next to a trigger: popover, menu, select, tooltip.
     The position (left/top) and the custom properties are written by lib/floating.ts. */
  .er-floating {
    position: fixed;
    top: 0;
    left: 0;
    z-index: var(--er-z-overlay);
    width: max-content;
    max-width: calc(100vw - 1rem);
    transform-origin: var(--er-transform-origin, center);
    outline: none;
  }

  .er-pop-enter-active,
  .er-pop-leave-active {
    transition:
      opacity var(--er-duration) var(--er-ease),
      transform var(--er-duration) var(--er-ease);
  }

  .er-pop-enter-from,
  .er-pop-leave-to {
    opacity: 0;
    transform: scale(0.96);
  }
}

collection.content:
export type Orientation = 'horizontal' | 'vertical'

/**
 * Arrow-key navigation for a list of items (tabs, menu items, options).
 * Returns the item the key should move to, or null if the key is not a navigation key.
 */
export function arrowTarget(
  event: KeyboardEvent,
  items: HTMLElement[],
  orientation: Orientation = 'vertical',
  loop = true,
): HTMLElement | null {
  if (items.length === 0) return null

  const previousKey = orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp'
  const nextKey = orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown'
  const current = items.indexOf(document.activeElement as HTMLElement)
  const last = items.length - 1

  switch (event.key) {
    case 'Home':
      return items[0] ?? null
    case 'End':
      return items[last] ?? null
    case nextKey: {
      if (current === -1) return items[0] ?? null
      if (current === last) return loop ? (items[0] ?? null) : null
      return items[current + 1] ?? null
    }
    case previousKey: {
      if (current === -1) return items[last] ?? null
      if (current === 0) return loop ? (items[last] ?? null) : null
      return items[current - 1] ?? null
    }
    default:
      return null
  }
}

/**
 * Type-to-select: returns a function that, given a keydown and the current items,
 * returns the item whose text starts with what the user has typed recently.
 */
export function createTypeahead(resetAfter = 500) {
  let buffer = ''
  let timer: ReturnType<typeof setTimeout> | undefined

  return (event: KeyboardEvent, items: HTMLElement[]): HTMLElement | null => {
    if (event.key.length !== 1 || event.ctrlKey || event.metaKey || event.altKey) return null
    // A lone space activates the focused item; it only extends a search already in progress.
    if (event.key === ' ' && buffer === '') return null

    buffer += event.key.toLowerCase()
    clearTimeout(timer)
    timer = setTimeout(() => {
      buffer = ''
    }, resetAfter)

    // Repeating one letter cycles through the items that start with it.
    const repeated = buffer.split('').every((char) => char === buffer[0])
    const query = repeated ? (buffer[0] ?? '') : buffer
    const start = items.indexOf(document.activeElement as HTMLElement)
    const offset = repeated || buffer.length === 1 ? 1 : 0
    const ordered = [...items.slice(start + offset), ...items.slice(0, start + offset)]

    return ordered.find((item) => (item.textContent ?? '').trim().toLowerCase().startsWith(query)) ?? null
  }
}

context.content:
import { inject, provide, type InjectionKey } from 'vue'

/**
 * Typed provide/inject pair for compound components.
 * `const [provideTabs, useTabs] = createContext<TabsContext>('Tabs')`
 */
export function createContext<T>(name: string) {
  const key: InjectionKey<T> = Symbol(name)

  function provideContext(value: T): T {
    provide(key, value)
    return value
  }

  function useContext(): T {
    const value = inject(key, null)
    if (value === null) throw new Error(`[ermine] This component must be used inside <${name}>.`)
    return value
  }

  return [provideContext, useContext] as const
}

floating.content:
import { toValue, watch, type MaybeRefOrGetter, type Ref } from 'vue'

export type Side = 'top' | 'right' | 'bottom' | 'left'
export type Align = 'start' | 'center' | 'end'

export interface FloatingOptions {
  /** Preferred side of the anchor. Flips to the opposite side when there is no room. */
  side?: Side
  /** Alignment along the anchor's edge. */
  align?: Align
  /** Gap between anchor and floating element, in px. */
  sideOffset?: number
  /** Shift along the aligned edge, in px. */
  alignOffset?: number
  /** Minimum distance kept from the viewport edge, in px. */
  padding?: number
}

interface Box {
  top: number
  right: number
  bottom: number
  left: number
  width: number
  height: number
}

export interface Placement {
  x: number
  y: number
  side: Side
  /** Space available on the chosen side, in px — useful as a max-height / max-width. */
  available: number
}

const OPPOSITE: Record<Side, Side> = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' }
const ORIGIN: Record<Side, string> = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' }

const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(value, max))

/** Pure placement maths: where a `width` × `height` box goes next to `anchor` inside `viewport`. */
export function computePlacement(
  anchor: Box,
  width: number,
  height: number,
  viewport: { width: number; height: number },
  options: FloatingOptions = {},
): Placement {
  const { align = 'center', sideOffset = 0, alignOffset = 0, padding = 8 } = options
  let side = options.side ?? 'bottom'

  const space: Record<Side, number> = {
    top: anchor.top - padding - sideOffset,
    bottom: viewport.height - anchor.bottom - padding - sideOffset,
    left: anchor.left - padding - sideOffset,
    right: viewport.width - anchor.right - padding - sideOffset,
  }

  const vertical = side === 'top' || side === 'bottom'
  const needed = vertical ? height : width
  if (space[side] < needed && space[OPPOSITE[side]] > space[side]) side = OPPOSITE[side]

  let x: number
  let y: number
  if (vertical) {
    y = side === 'bottom' ? anchor.bottom + sideOffset : anchor.top - height - sideOffset
    if (align === 'start') x = anchor.left + alignOffset
    else if (align === 'end') x = anchor.right - width - alignOffset
    else x = anchor.left + anchor.width / 2 - width / 2
    x = clamp(x, padding, viewport.width - width - padding)
  } else {
    x = side === 'right' ? anchor.right + sideOffset : anchor.left - width - sideOffset
    if (align === 'start') y = anchor.top + alignOffset
    else if (align === 'end') y = anchor.bottom - height - alignOffset
    else y = anchor.top + anchor.height / 2 - height / 2
    y = clamp(y, padding, viewport.height - height - padding)
  }

  return { x, y, side, available: Math.max(0, space[side]) }
}

/**
 * Keeps `floating` positioned next to `anchor` while `active` is true.
 * Give the floating element the `.er-floating` class (position: fixed).
 *
 * Besides left/top it sets, on the floating element:
 *   data-side                 the side it actually ended up on
 *   --er-anchor-width         width of the anchor (e.g. min-width for a select)
 *   --er-available-size       free space on that side (e.g. a max-height)
 *   --er-transform-origin     so scale animations grow from the anchor
 */
export function useFloating(
  anchor: Ref<HTMLElement | null | undefined>,
  floating: Ref<HTMLElement | null | undefined>,
  active: MaybeRefOrGetter<boolean>,
  options: FloatingOptions = {},
) {
  function update() {
    const anchorEl = anchor.value
    const floatingEl = floating.value
    if (!anchorEl || !floatingEl) return

    const rect = anchorEl.getBoundingClientRect()
    const placement = computePlacement(
      rect,
      floatingEl.offsetWidth,
      floatingEl.offsetHeight,
      { width: document.documentElement.clientWidth, height: window.innerHeight },
      options,
    )

    floatingEl.style.left = `${Math.round(placement.x)}px`
    floatingEl.style.top = `${Math.round(placement.y)}px`
    floatingEl.dataset.side = placement.side
    floatingEl.style.setProperty('--er-anchor-width', `${Math.round(rect.width)}px`)
    floatingEl.style.setProperty('--er-available-size', `${Math.floor(placement.available)}px`)
    floatingEl.style.setProperty('--er-transform-origin', ORIGIN[placement.side])
  }

  watch(
    [() => (toValue(active) ? anchor.value : null), floating],
    ([anchorEl, floatingEl], _previous, onCleanup) => {
      if (!anchorEl || !floatingEl) return

      let frame = 0
      const schedule = () => {
        cancelAnimationFrame(frame)
        frame = requestAnimationFrame(update)
      }

      update()
      const observer = new ResizeObserver(schedule)
      observer.observe(anchorEl)
      observer.observe(floatingEl)
      window.addEventListener('scroll', schedule, { capture: true, passive: true })
      window.addEventListener('resize', schedule)

      onCleanup(() => {
        cancelAnimationFrame(frame)
        observer.disconnect()
        window.removeEventListener('scroll', schedule, { capture: true })
        window.removeEventListener('resize', schedule)
      })
    },
    { flush: 'post', immediate: true },
  )

  return { update }
}

layer.content:
import { toValue, watch, type MaybeRefOrGetter, type Ref } from 'vue'

export type DismissReason = 'escape' | 'outside'

export interface LayerOptions {
  /** Called when the user presses Escape or presses outside the layer. */
  onDismiss: (reason: DismissReason, event: Event) => void
  /** Extra elements that count as "inside" — usually the trigger, which toggles on its own. */
  ignore?: () => Array<HTMLElement | null | undefined>
  /** Keep Tab / Shift+Tab cycling inside the layer. */
  loopFocus?: boolean
  /** Pull focus back if it lands outside the layer (modal dialogs). */
  modal?: boolean
  /** What to focus on open. Defaults to the first tabbable element, else the layer. Return false to leave focus alone. */
  initialFocus?: () => HTMLElement | null | undefined | false
  /** Return focus to where it was when the layer closes. Default true. */
  restoreFocus?: boolean
}

interface Layer {
  el: HTMLElement
  options: LayerOptions
}

/** Open layers, oldest first. The last entry is the one the user is interacting with. */
const stack: Layer[] = []

/** Put this attribute on anything that should never count as "outside" (e.g. the toaster). */
const IGNORE_SELECTOR = '[data-er-layer-ignore]'

const TABBABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[contenteditable]:not([contenteditable="false"])',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

/** Elements inside `root` that Tab can reach, in DOM order. */
export function tabbables(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(TABBABLE_SELECTOR)).filter(
    (el) => el.tabIndex >= 0 && !el.closest('[inert]') && el.getClientRects().length > 0,
  )
}

/**
 * Safari does not focus a button when it is clicked, so "where was focus when this opened?" comes back
 * empty there. Remembering what was last pressed gives the layer somewhere to return focus to anyway.
 */
let lastPressed: { el: HTMLElement; at: number } | undefined
let trackingPresses = false

function trackPresses() {
  if (trackingPresses || typeof document === 'undefined') return
  trackingPresses = true
  document.addEventListener(
    'pointerdown',
    (event) => {
      const el = event.target instanceof Element ? event.target.closest<HTMLElement>(TABBABLE_SELECTOR) : null
      lastPressed = el ? { el, at: performance.now() } : undefined
    },
    true,
  )
}

/** The control pressed a moment ago, if it is still on the page. */
function recentlyPressed(): HTMLElement | null {
  return lastPressed && lastPressed.el.isConnected && performance.now() - lastPressed.at < 1000 ? lastPressed.el : null
}

function isIgnored(target: Node): boolean {
  return target instanceof Element && target.closest(IGNORE_SELECTOR) !== null
}

function isInside(layer: Layer, target: Node): boolean {
  if (layer.el.contains(target) || isIgnored(target)) return true
  return layer.options.ignore?.().some((el) => el?.contains(target)) ?? false
}

function onPointerDown(event: PointerEvent) {
  const target = event.target
  if (!(target instanceof Node)) return
  // Walk from the top layer down: a press inside a layer protects it and everything beneath it.
  for (const layer of [...stack].reverse()) {
    if (isInside(layer, target)) break
    layer.options.onDismiss('outside', event)
  }
}

function onKeyDown(event: KeyboardEvent) {
  const top = stack[stack.length - 1]
  if (!top || event.isComposing) return

  if (event.key === 'Escape') {
    top.options.onDismiss('escape', event)
    return
  }

  if (event.key === 'Tab' && top.options.loopFocus) {
    const items = tabbables(top.el)
    const active = document.activeElement
    const first = items[0]
    const last = items[items.length - 1]
    if (!first || !last) {
      event.preventDefault()
      top.el.focus()
    } else if (!top.el.contains(active)) {
      event.preventDefault()
      first.focus()
    } else if (event.shiftKey && (active === first || active === top.el)) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && active === last) {
      event.preventDefault()
      first.focus()
    }
  }
}

function onFocusIn(event: FocusEvent) {
  const top = stack[stack.length - 1]
  const target = event.target
  if (!top?.options.modal || !(target instanceof Node)) return
  if (top.el.contains(target) || isIgnored(target)) return
  ;(tabbables(top.el)[0] ?? top.el).focus({ preventScroll: true })
}

function listen(on: boolean) {
  const method = on ? 'addEventListener' : 'removeEventListener'
  document[method]('pointerdown', onPointerDown as EventListener, true)
  document[method]('keydown', onKeyDown as EventListener)
  document[method]('focusin', onFocusIn as EventListener)
}

/**
 * Turns `el` into a dismissable layer while `active` is true: Escape and outside
 * presses call `onDismiss`, focus moves in on open and back out on close, and
 * nested layers (a select inside a dialog) close one at a time, innermost first.
 */
export function useLayer(
  el: Ref<HTMLElement | null | undefined>,
  active: MaybeRefOrGetter<boolean>,
  options: LayerOptions,
) {
  trackPresses()

  watch(
    () => (toValue(active) ? el.value : null),
    (target, _previous, onCleanup) => {
      if (!target) return

      const layer: Layer = { el: target, options }
      const focused = document.activeElement
      const previous = focused instanceof HTMLElement && focused !== document.body ? focused : recentlyPressed()

      stack.push(layer)
      if (stack.length === 1) listen(true)

      const initial = options.initialFocus ? options.initialFocus() : undefined
      if (initial !== false) (initial ?? tabbables(target)[0] ?? target).focus({ preventScroll: true })

      onCleanup(() => {
        const index = stack.indexOf(layer)
        if (index > -1) stack.splice(index, 1)
        if (stack.length === 0) listen(false)

        if (options.restoreFocus === false || !previous?.isConnected) return
        // Only hand focus back if it is still ours to give — not if the user already moved on.
        const current = document.activeElement
        if (!current || current === document.body || target.contains(current)) {
          previous.focus({ preventScroll: true })
        }
      })
    },
    { flush: 'post', immediate: true },
  )
}

primitive.content:
import {
  cloneVNode,
  Comment,
  defineComponent,
  Fragment,
  h,
  onMounted,
  ref,
  Teleport,
  Text,
  type Component,
  type PropType,
  type VNode,
} from 'vue'

function firstElement(nodes: VNode[]): VNode | undefined {
  for (const node of nodes) {
    if (node.type === Comment || node.type === Text) continue
    if (node.type === Fragment) {
      const inner = Array.isArray(node.children) ? firstElement(node.children as VNode[]) : undefined
      if (inner) return inner
      continue
    }
    return node
  }
  return undefined
}

/**
 * Renders `as` (a tag name or component). With `as-child`, it renders nothing of
 * its own and instead passes its attributes and listeners to the single child in
 * its slot — so `<DialogTrigger as-child><Button>Open</Button></DialogTrigger>`
 * produces one button, not two.
 */
export const Primitive = defineComponent({
  name: 'Primitive',
  inheritAttrs: false,
  props: {
    as: { type: [String, Object, Function] as PropType<string | Component>, default: 'div' },
    asChild: Boolean,
  },
  setup(props, { attrs, slots }) {
    return () => {
      if (props.asChild) {
        const child = firstElement(slots.default?.() ?? [])
        if (!child) return null
        // Classes, styles and listeners from both sides are merged. For anything else,
        // what you wrote on the child (an id, a type) wins over what the parent passes down.
        const clone = cloneVNode(child, attrs, true)
        for (const key in child.props) {
          if (key !== 'class' && key !== 'style' && !/^on[A-Z]/.test(key)) clone.props![key] = child.props[key]
        }
        return clone
      }
      return typeof props.as === 'string'
        ? h(props.as, attrs, slots.default?.())
        : h(props.as as Component, attrs, slots)
    }
  },
})

/**
 * Teleports its slot to `to` (default: body), but only after mount. Rendering
 * nothing on the server keeps hydration safe in Nuxt and in Astro islands.
 */
export const Portal = defineComponent({
  name: 'Portal',
  props: {
    to: { type: [String, Object] as PropType<string | HTMLElement>, default: 'body' },
  },
  setup(props, { slots }) {
    const mounted = ref(false)
    onMounted(() => {
      mounted.value = true
    })
    return () => (mounted.value ? h(Teleport, { to: props.to }, slots.default?.() ?? []) : null)
  },
})

/** Resolves a template ref (element or component instance) to its root element. */
export function toElement(target: unknown): HTMLElement | null {
  if (typeof HTMLElement === 'undefined' || !target) return null
  const el = (target as { $el?: unknown }).$el ?? target
  return el instanceof HTMLElement ? el : null
}

scroll-lock.content:
let locks = 0
let restore: (() => void) | undefined

/**
 * Stops the page behind a modal from scrolling. Returns the function that
 * releases the lock. Locks are counted, so nested modals behave.
 */
export function lockScroll(): () => void {
  if (typeof document === 'undefined') return () => {}

  if (locks++ === 0) {
    const root = document.documentElement
    const previous = { overflow: root.style.overflow, paddingRight: root.style.paddingRight }
    const scrollbar = window.innerWidth - root.clientWidth

    root.style.overflow = 'hidden'
    // Reserve the space the scrollbar took so the page does not shift sideways.
    if (scrollbar > 0) {
      const current = Number.parseFloat(getComputedStyle(root).paddingRight) || 0
      root.style.paddingRight = `${current + scrollbar}px`
    }

    restore = () => {
      root.style.overflow = previous.overflow
      root.style.paddingRight = previous.paddingRight
    }
  }

  let released = false
  return () => {
    if (released) return
    released = true
    if (--locks === 0) {
      restore?.()
      restore = undefined
    }
  }
}

