/** Avatar — a round picture of a person or team, falling back to initials when there is no image. Stack several with AvatarGroup. */
export { default as Avatar } from './Avatar.vue'
export { default as AvatarGroup } from './AvatarGroup.vue'

/** Breadcrumb — the trail of pages leading to the current one, as links with separators. */
export { default as Breadcrumb } from './Breadcrumb.vue'
export { default as BreadcrumbItem } from './BreadcrumbItem.vue'

/**
 * Dates are plain 'YYYY-MM-DD' strings, the format <input type="date"> uses: no time
 * and no time zone, so a date never shifts by a day between server and browser.
 * Strings in this format sort in date order, so they can be compared with < and >.
 */

const DAY = 86_400_000

/** The date as a Date at UTC midnight, or null if the string is not a real date. */
export function parseDate(value: string | null | undefined): Date | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value ?? '')
  if (!match) return null
  const date = new Date(0)
  date.setUTCFullYear(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
  // Rejects overflow such as 2026-02-31, which Date would roll into March.
  return toDateString(date) === value ? date : null
}

export function toDateString(date: Date): string {
  return date.toISOString().slice(0, 10)
}

/** Today in the visitor's own time zone. */
export function today(): string {
  const now = new Date()
  return toDateString(new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())))
}

export function addDays(value: string, days: number): string {
  const date = parseDate(value)
  return date ? toDateString(new Date(date.getTime() + days * DAY)) : value
}

/** Same day in another month, pulled back to the last day when that month is shorter. */
export function addMonths(value: string, months: number): string {
  const date = parseDate(value)
  if (!date) return value
  const first = new Date(0)
  first.setUTCFullYear(date.getUTCFullYear(), date.getUTCMonth() + months, 1)
  const daysInMonth = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0)).getUTCDate()
  first.setUTCDate(Math.min(date.getUTCDate(), daysInMonth))
  return toDateString(first)
}

export function startOfMonth(value: string): string {
  return `${value.slice(0, 7)}-01`
}

/** Day of the week, 0 (Sunday) to 6 (Saturday). */
export function weekday(value: string): number {
  return parseDate(value)?.getUTCDay() ?? 0
}

/** Formats a date string for display. Returns '' for anything that is not a date. */
export function formatDate(value: string | null | undefined, locale: string, options: Intl.DateTimeFormatOptions): string {
  const date = parseDate(value)
  return date ? new Intl.DateTimeFormat(locale, { ...options, timeZone: 'UTC' }).format(date) : ''
}

/** Calendar — a month grid for choosing one date, with full keyboard navigation and min / max limits. */
export { default as Calendar } from './Calendar.vue'
export * from './dates'

/** Carousel — slides you swipe, scroll or step through with buttons, built on native scroll snapping. */
export { default as Carousel } from './Carousel.vue'
export { default as CarouselSlide } from './CarouselSlide.vue'

export interface ChartSeries {
  /** Property of each data row that holds this series' number. */
  key: string
  /** Name shown in the legend, the readout and the table. Defaults to the key. */
  label?: string
  /** Any CSS colour. Defaults to the next --er-chart-N variable, in order. */
  color?: string
}

function niceStep(rough: number): number {
  const power = 10 ** Math.floor(Math.log10(rough))
  const fraction = rough / power
  const nice = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10
  return nice * power
}

/** A value axis that covers min..max and lands on round numbers (0, 500, 1,000 ...). */
export function niceScale(min: number, max: number, count = 4): { min: number; max: number; ticks: number[] } {
  if (min === max) max = min + 1
  const step = niceStep((max - min) / count)
  const low = Math.floor(min / step) * step
  const high = Math.ceil(max / step) * step
  const ticks: number[] = []
  // Rounded on the way in, so 0.1 + 0.2 does not become a tick labelled 0.30000000000000004.
  for (let index = 0; low + index * step <= high + step / 2; index++) ticks.push(Number((low + index * step).toFixed(10)))
  return { min: low, max: high, ticks }
}

/** A number from a data row, or null when the cell is empty or not a number. */
export function toNumber(value: unknown): number | null {
  if (value === null || value === undefined || value === '') return null
  const number = Number(value)
  return Number.isFinite(number) ? number : null
}

/** Rough width of a short label at the chart's 12px text size — enough to reserve room for it. */
export function textWidth(text: string): number {
  return text.length * 6.6
}

/**
 * A bar from `base` to `end` with its data end rounded and its base square.
 * Works in both directions, so negative bars round at the bottom.
 */
export function barPath(x: number, base: number, end: number, width: number, radius = 4): string {
  const r = Math.min(radius, width / 2, Math.abs(base - end))
  const turn = end < base ? r : -r
  return `M${x},${base}V${end + turn}Q${x},${end} ${x + r},${end}H${x + width - r}Q${x + width},${end} ${x + width},${end + turn}V${base}Z`
}

/** One entry in a chart's legend. */
export interface ChartLegendItem {
  name: string
  color: string
  /** Switched off by the reader. Still listed, so it can be switched back on. */
  hidden?: boolean
}

/** A ring segment (or a pie slice when `inner` is 0) between two angles, in radians from 12 o'clock. */
export function arcPath(cx: number, cy: number, outer: number, inner: number, from: number, to: number): string {
  // A complete circle has the same start and end point, which draws nothing; stop a hair short.
  const end = Math.min(to, from + Math.PI * 2 - 0.0001)
  const point = (radius: number, angle: number) => `${cx + radius * Math.sin(angle)},${cy - radius * Math.cos(angle)}`
  const large = end - from > Math.PI ? 1 : 0
  const outerArc = `M${point(outer, from)}A${outer},${outer} 0 ${large} 1 ${point(outer, end)}`
  return inner > 0
    ? `${outerArc}L${point(inner, end)}A${inner},${inner} 0 ${large} 0 ${point(inner, from)}Z`
    : `${outerArc}L${cx},${cy}Z`
}

import type { Ref } from 'vue'
import { createContext } from '../../lib/context'

export interface CollapsibleContext {
  open: Ref<boolean>
  toggle: () => void
  disabled: Ref<boolean>
  contentId: string
}

export const [provideCollapsible, useCollapsible] = createContext<CollapsibleContext>('Collapsible')

/** Hue 0–360, saturation and value 0–1: the model the picker's square and slider work in. */
export interface Hsv {
  h: number
  s: number
  v: number
}

/** '#rrggbb' from '#rgb', '#rrggbb' or the same without the hash; undefined for anything else. */
export function normalizeHex(input: string): string | undefined {
  const text = input.trim().replace(/^#/, '').toLowerCase()
  if (/^[0-9a-f]{3}$/.test(text)) return `#${[...text].map((char) => char + char).join('')}`
  return /^[0-9a-f]{6}$/.test(text) ? `#${text}` : undefined
}

export function hexToHsv(hex: string): Hsv {
  const value = normalizeHex(hex) ?? '#000000'
  const [r, g, b] = [1, 3, 5].map((start) => Number.parseInt(value.slice(start, start + 2), 16) / 255) as [number, number, number]
  const max = Math.max(r, g, b)
  const delta = max - Math.min(r, g, b)
  let h = 0
  if (delta) {
    if (max === r) h = ((g - b) / delta) % 6
    else if (max === g) h = (b - r) / delta + 2
    else h = (r - g) / delta + 4
  }
  return { h: (h * 60 + 360) % 360, s: max ? delta / max : 0, v: max }
}

export function hsvToHex({ h, s, v }: Hsv): string {
  const channel = (offset: number) => {
    const k = (offset + h / 60) % 6
    return Math.round((v - v * s * Math.max(0, Math.min(k, 4 - k, 1))) * 255)
      .toString(16)
      .padStart(2, '0')
  }
  return `#${channel(5)}${channel(3)}${channel(1)}`
}

