/** Field — ties a label, hint and error message to any control, with a small validation helper. */
export { default as Field } from './Field.vue'
export * from './validation'

import { reactive, toValue, watch, type MaybeRefOrGetter } from 'vue'

/** Returns the message to show when the value is not acceptable, or nothing when it is. */
export type Rule<T = unknown> = (value: T) => string | undefined | null | false

const isEmpty = (value: unknown) =>
  value === undefined || value === null || value === '' || value === false || (Array.isArray(value) && value.length === 0)

/** Something must be entered, chosen or ticked. */
export const required =
  (message = 'This field is required.'): Rule =>
  (value) =>
    isEmpty(value) && message

// The rules below pass on an empty value, so "optional, but if given it must be an email" needs no extra code.
// Combine with required() when the field must be filled in.

export const minLength =
  (length: number, message = `Use at least ${length} characters.`): Rule =>
  (value) =>
    !isEmpty(value) && String(value).length < length && message

export const maxLength =
  (length: number, message = `Use at most ${length} characters.`): Rule =>
  (value) =>
    !isEmpty(value) && String(value).length > length && message

export const pattern =
  (expression: RegExp, message = 'This is not in the expected format.'): Rule =>
  (value) =>
    !isEmpty(value) && !expression.test(String(value)) && message

export const email = (message = 'Enter an email address, such as name@example.com.'): Rule => pattern(/^[^\s@]+@[^\s@]+\.[^\s@]+$/, message)

export const min =
  (limit: number, message = `Enter ${limit} or more.`): Rule =>
  (value) =>
    !isEmpty(value) && Number(value) < limit && message

export const max =
  (limit: number, message = `Enter ${limit} or less.`): Rule =>
  (value) =>
    !isEmpty(value) && Number(value) > limit && message

/** The first message from `rules` that applies to `value`, or undefined when every rule passes. */
export function check<T>(value: T, rules: ReadonlyArray<Rule<T>> = []): string | undefined {
  for (const rule of rules) {
    const message = rule(value)
    if (message) return message
  }
  return undefined
}

/**
 * Validation for a group of values.
 *
 *   const form = useValidation(() => answers, { email: [required(), email()] })
 *   form.errors.email      the message to show, once the field has been checked
 *   form.validate()        check everything (or just the named fields); true when all pass
 *   form.touch('email')    check one field — bind it to @blur
 *
 * A field is quiet until it is checked. Once it shows an error, it is re-checked as the
 * value changes, so the message clears the moment the problem is fixed.
 */
export function useValidation<T extends Record<string, unknown>>(
  values: MaybeRefOrGetter<T>,
  rules: { [K in keyof T]?: ReadonlyArray<Rule<T[K]>> },
) {
  const keys = Object.keys(rules) as Array<keyof T & string>
  const errors = reactive({}) as { [K in keyof T]?: string }

  function touch(key: keyof T & string): boolean {
    const message = check(toValue(values)[key], rules[key])
    ;(errors as Record<string, string | undefined>)[key] = message
    return !message
  }

  function validate(only: ReadonlyArray<keyof T & string> = keys): boolean {
    // Every field is checked, not just up to the first failure, so all the messages appear at once.
    return only.map(touch).every(Boolean)
  }

  function reset() {
    for (const key of keys) (errors as Record<string, string | undefined>)[key] = undefined
  }

  for (const key of keys) {
    watch(
      () => toValue(values)[key],
      () => {
        if (errors[key]) touch(key)
      },
      { deep: true },
    )
  }

  return { errors, validate, touch, reset }
}

import type { Directive } from 'vue'
import { haptic, type HapticName } from './haptic'

/**
 * v-haptic — a small buzz when a control is used, on phones that can. Pairs well with v-sound.
 *
 *   <Button v-haptic>Save</Button>                 a normal press
 *   <Button v-haptic="'heavy'">Delete</Button>     a named pattern
 *   <Switch v-haptic.toggle />                     firmer when switching on than off
 *   <Button v-haptic="false">Quiet</Button>        switched off
 */
type HapticBinding = HapticName | boolean | undefined

interface State {
  value: HapticBinding
  toggle: boolean
  onClick: () => void
}

const states = new WeakMap<HTMLElement, State>()

function isOn(el: HTMLElement): boolean {
  if (el instanceof HTMLInputElement) return el.checked
  return el.getAttribute('aria-pressed') === 'true' || el.getAttribute('aria-checked') === 'true'
}

export const vHaptic: Directive<HTMLElement, HapticBinding> = {
  mounted(el, binding) {
    const state: State = {
      value: binding.value,
      toggle: !!binding.modifiers.toggle,
      onClick: () => {
        if (state.value === false) return
        // Checked after the control has updated itself, so the buzz matches where it ended up.
        if (state.toggle) queueMicrotask(() => haptic(isOn(el) ? 'medium' : 'light'))
        else haptic(typeof state.value === 'string' ? state.value : 'medium')
      },
    }
    states.set(el, state)
    el.addEventListener('click', state.onClick)
  },
  updated(el, binding) {
    const state = states.get(el)
    if (state) state.value = binding.value
  },
  unmounted(el) {
    const state = states.get(el)
    if (!state) return
    el.removeEventListener('click', state.onClick)
    states.delete(el)
  },
}

import { effectScope, reactive, watch } from 'vue'

/**
 * Vibration feedback through the Vibration API. Android phones support it; iPhones and desktop
 * browsers do not, and there it quietly does nothing — so treat it as a garnish, never as the message.
 */

/** Each pattern is milliseconds of buzz, pause, buzz, pause ... Short and light: a tap, not an alarm. */
const PATTERNS = {
  /** The lightest touch: a key press, a selection moving. */
  light: [8],
  /** A normal button press. The default. */
  medium: [14],
  /** Something weighty: confirming, deleting. */
  heavy: [26],
  /** Two quick taps: it worked. */
  success: [12, 60, 18],
  /** Three firm taps: it did not. */
  error: [22, 50, 22, 50, 22],
  /** A tiny tick, for stepping through values (a slider, a picker). */
  selection: [4],
} satisfies Record<string, number[]>

export type HapticName = keyof typeof PATTERNS
export const hapticNames = Object.keys(PATTERNS) as HapticName[]

const STORAGE_KEY = 'er-haptics'

/** Whether vibration is used. Shared by the whole page and remembered between visits. */
export const hapticSettings = reactive({ enabled: true })

let ready = false
function prepare() {
  if (ready || typeof window === 'undefined') return
  ready = true
  try {
    const saved = JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? 'null') as { enabled?: unknown } | null
    if (typeof saved?.enabled === 'boolean') hapticSettings.enabled = saved.enabled
    // Someone who has asked their system for less motion gets no buzzing until they ask for it.
    else if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) hapticSettings.enabled = false
  } catch {
    // Storage can be blocked. The default still works.
  }
  effectScope(true).run(() =>
    watch(
      () => hapticSettings.enabled,
      (enabled) => {
        try {
          window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ enabled }))
        } catch {
          // Not being able to save the choice is not worth interrupting anyone for.
        }
      },
    ),
  )
}

/**
 * For use inside components: `const { haptic, settings, supported } = useHaptics()`. Calling it
 * loads the saved choice straight away, which is what a settings switch bound to `settings.enabled` needs.
 */
export function useHaptics() {
  prepare()
  return { haptic, settings: hapticSettings, supported: canVibrate() }
}

/** True where the device can vibrate at all. Use it to hide a "vibration" setting that would do nothing. */
export function canVibrate(): boolean {
  return typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function'
}

/**
 * Vibrates now, unless haptics are switched off or the device cannot. Returns whether it buzzed.
 * Browsers only allow this in response to a tap or key press.
 */
export function haptic(name: HapticName | number[] = 'medium'): boolean {
  prepare()
  if (!hapticSettings.enabled || !canVibrate()) return false
  const pattern = typeof name === 'string' ? PATTERNS[name] : name
  if (!pattern) return false
  try {
    return navigator.vibrate(pattern)
  } catch {
    return false
  }
}

/** Haptics — short vibration patterns for presses and results on phones that support it, added with v-haptic. */
export { vHaptic } from './directive'
export { canVibrate, haptic, hapticNames, hapticSettings, useHaptics, type HapticName } from './haptic'

import type { Ref } from 'vue'
import { createContext } from '../../lib/context'

export interface HoverCardContext {
