/*
 * Fluid type. One rule sizes every piece of fluid text; an element only says which step of the
 * scale it is, with --er-step (0 is body text, 1 is one size up, -1 one size down, halves allowed).
 *
 * The size is a clamp() of three values:
 *   the smallest it gets  — the narrow-screen size
 *   a value that grows with the available width
 *   the largest it gets   — the wide-screen size
 * The growing value is written as "rem + a share of the width", never width alone, so the text still
 * gets bigger when the reader raises their browser's text size.
 *
 * The scale itself comes from the --er-type-* variables in ermine.css. The fallbacks here are the same
 * values, so the component also works with a stylesheet that predates them.
 */
@layer components {
  .er-fluid-type,
  .er-prose,
  .er-prose :is(h1, h2, h3, h4, h5, h6, small, figcaption, pre, code) {
    --er-type-step-min: calc(var(--er-type-min, 1) * pow(var(--er-type-ratio-min, 1.2), var(--er-step, 0)));
    --er-type-step-max: calc(var(--er-type-max, 1.125) * pow(var(--er-type-ratio-max, 1.3), var(--er-step, 0)));
    font-size: clamp(
      calc(var(--er-type-step-min) * 1rem),
      calc(
        var(--er-type-step-min) * 1rem + (var(--er-type-step-max) - var(--er-type-step-min)) *
          (var(--er-fluid-width, 100vw) - var(--er-type-from, 20rem)) / var(--er-type-range, 60)
      ),
      calc(var(--er-type-step-max) * 1rem)
    );
  }

  /* Put this class on a box (a card, a sidebar, a panel) and the fluid text inside it sizes itself
     to that box instead of to the screen: the same heading is smaller in a narrow column. */
  .er-fluid-container {
    container-type: inline-size;
    --er-fluid-width: 100cqi;
  }
}

